local a={}a.__index=a;function a.new()return setmetatable({},a)end;local function b(c)if c<0 then return 0 elseif c>1 then return 1 else return c end end;local d={YFL=1,YFR=-1,YRL=-1,YRR=1}local e={YFL=1,YFR=-1,YRL=1,YRR=-1}local f={YRL=-1,YRR=1}function a:mixLateral(g,h,i)local j={}for k,l in pairs(d)do j[k]=b((e[k]or 0)*(g or 0)+l*(h or 0)+(f[k]or 0)*(i or 0))end;return j end;function a:mixYaw(h)return self:mixLateral(0,h)end;function a:mixSurge(m)m=m or 0;return{MAIN=m>0 and b(m)or 0,FRL=m<0 and b(-m)or 0,FRR=m<0 and b(-m)or 0}end;local function n(o,p,q)local r,s,t,u=o+p+q,o+p-q,o-p+q,o-p-q;local v=math.min(r,s,t,u)local w=math.max(r,s,t,u)local x=w-v;if x>1 then local y=1/x;p,q=p*y,q*y;r,s,t,u=o+p+q,o+p-q,o-p+q,o-p-q;v=math.min(r,s,t,u)w=math.max(r,s,t,u)end;local z=0;if v<0 then z=-v elseif w>1 then z=1-w end;return b(r+z),b(s+z),b(t+z),b(u+z)end;function a:mix(A)local r,s,t,u=n(A.heave or 0,A.pitch or 0,A.roll or 0)local j={FL=r,FR=s,RL=t,RR=u}for k,B in pairs(self:mixLateral(A.sway,A.yaw,A.yawRear))do j[k]=B end;for k,B in pairs(self:mixSurge(A.surge))do j[k]=B end;return j end;return a